#[path="../../../packages/core/src/loudness.rs"] mod loudness;
fn main(){let seconds:usize=std::env::args().nth(1).and_then(|s|s.parse().ok()).unwrap_or(120);let pcm:Vec<Vec<f32>>=(0..12).map(|c|(0..1024).map(|i|((i as f32*(0.01+c as f32*0.003)).sin())*0.12).collect()).collect();let mut m=loudness::LoudnessMeter::speakers_7_1_4();let start=std::time::Instant::now();for _ in 0..seconds*48000/1024{m.push(&pcm);let _=m.integrated();}println!("{}",serde_json::json!({"seconds":seconds,"elapsedMs":start.elapsed().as_secs_f64()*1000.,"measurement":m.integrated()}));}
